//! Auto-generated tool guide — single source of truth for MCP tool documentation.
//!
//! This module generates the `tools.md` rule file that replaces the hardcoded
//! tool sections in `system_prompt.rs`. By generating tool guidance from code,
//! it can never drift from reality.

/// Build the tool guide markdown content.
///
/// This is the single source of truth for all MCP tool documentation emitted
/// by magistr. The output is written to `.claude/rules/tools.md` (Overwrite policy)
/// and included in Cursor/Copilot/Cline/Windsurf instructions.
pub(crate) fn build_tool_guide() -> String {
    let mut doc = String::with_capacity(3072);

    doc.push_str(
        "<!-- Auto-generated by magistr — DO NOT EDIT. Re-run `magistr init` to update. -->\n",
    );
    doc.push_str("# Tool Guide\n\n");

    // ── Codebase Navigation & Editing ──────────────────────────────
    doc.push_str("## Codebase Navigation & Editing (workbench-mcp)\n\n");
    doc.push_str("| Tool | Replaces | Purpose |\n");
    doc.push_str("|------|----------|---------|");
    for (tool, replaces, purpose) in WORKBENCH_TOOLS {
        doc.push_str(&format!("\n| `{tool}` | {replaces} | {purpose} |"));
    }
    doc.push_str("\n\n");
    doc.push_str(
        "Every call returns one envelope (`ok`, `results`, `freshness`, `budget`, `truncation`, \
         `notes`). Read `.claude/skills/workbench-routing/SKILL.md` for the routing table and \
         error recovery. Git stays in the shell.\n\n",
    );
    doc.push_str(
        "Recommended workflow: `map` → `search` → `read` → `edit` (parse-verified) → \
         `run` for the declared gates; `search mode:references` before touching shared code.\n\n",
    );

    // ── Roadmap, reasoning & execution ─────────────────────────────
    doc.push_str("## Roadmap, Reasoning & Execution (think-and-ship)\n\n");
    doc.push_str("| Family | Purpose | Key tools |\n");
    doc.push_str("|--------|---------|-----------|");
    for (family, purpose, key_tools) in THINK_AND_SHIP_FAMILIES {
        doc.push_str(&format!("\n| `{family}` | {purpose} | {key_tools} |"));
    }
    doc.push_str("\n\n");
    doc.push_str(
        "Served by the same `magistr` MCP server. A roadmap chunk is realized by a ship \
         objective, motivated by think reasoning; the plan is `ship_plan` (there is no plan \
         file) and `ROADMAP.md` is a generated view (`roadmap_export`), never the source of truth.\n\n",
    );

    doc.push_str(magistr_engine::prompt::PromptConfig::REASONING_GUIDANCE);
    doc.push_str("\n\n");

    // ── Quality & Workflow ─────────────────────────────────────────
    doc.push_str("## Quality & Workflow (magistr)\n\n");
    doc.push_str("| Tool | Purpose |\n");
    doc.push_str("|------|---------|");
    for (tool, purpose) in MAGISTR_TOOLS {
        doc.push_str(&format!("\n| `{tool}` | {purpose} |"));
    }
    doc.push_str("\n\n");

    // ── Tool Preferences ───────────────────────────────────────────
    doc.push_str("## Tool Preferences\n\n");
    for pref in PREFERENCES {
        doc.push_str(&format!("- {pref}\n"));
    }

    doc
}

